$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$utf8 = [Text.UTF8Encoding]::new($false)
$sections = @{
 'values' = 'Optional advertising requests\nThe game does not automatically preload rewarded ads. Tapping a button explicitly labelled Watch ad allows Google advertising requests for this app session and starts loading and showing an ad without a separate game confirmation. Before a shop reward, the displayed notice explains that Google loads the ad. UMP is accessed after that tap and may display any required Google privacy form. Without tapping an advertising button, the game does not request an ad. Settings lets you stop new advertising requests; this cannot undo an in-flight request, stop all processing inside an already initialized Google SDK, or delete data already sent to Google. Permission is not saved across app restarts or Activity recreation. Accepting the game privacy policy alone does not allow advertising requests. The advertising ID and Privacy Sandbox advertising permissions are explicitly removed from the app manifest; other available SDK identifiers may still be processed. Watching ads is optional. Shop rewards give at least 5,000 debris for one confirmed rewarded view, with the amount scaled to unlocked planets and fleet income, or one common case for three confirmed rewarded views. The game saves the case-view counter and pending reward identifier, type and quoted amount locally to prevent duplicate rewards. Closing an ad without earning its reward does not count. Rewarded bonuses are not cash. Cases can be obtained with earned game debris or rewarded ads. There are no real-money purchases.'
 'values-ru' = 'Добровольные рекламные запросы\nИгра не предзагружает рекламу автоматически. Нажатие кнопки с явной надписью Смотреть рекламу разрешает рекламные запросы Google в текущей сессии и запускает загрузку и показ без отдельного подтверждения игры. Перед наградой в магазине видимое пояснение сообщает о загрузке рекламы Google. После нажатия вызывается UMP, который может показать необходимую форму рекламной приватности Google. Без нажатия рекламной кнопки игра не запрашивает объявление. В настройках можно остановить новые запросы; это не отменяет запрос в процессе выполнения, не останавливает всю обработку уже инициализированного SDK Google и не удаляет отправленные Google данные. Разрешение не сохраняется после перезапуска или пересоздания Activity. Само принятие политики игры не разрешает рекламные запросы. Рекламный идентификатор и рекламные разрешения Privacy Sandbox исключены из манифеста; другие доступные идентификаторы SDK могут обрабатываться. Просмотр добровольный. В магазине один подтверждённый просмотр даёт от 5 000 обломков с ростом по открытым планетам и доходу флота; три подтверждённых просмотра дают обычный кейс. Счётчик просмотров для кейса, идентификатор, тип и показанная сумма ожидающей награды сохраняются локально для защиты от повторной выдачи. Закрытие рекламы без подтверждения награды не засчитывается. Рекламные бонусы не являются деньгами. Кейсы можно получить за игровой мусор или просмотры рекламы. Покупок за реальные деньги нет.'
 'values-es' = 'Solicitudes publicitarias opcionales\nEl juego no precarga anuncios automáticamente. Al pulsar un botón que indica Ver anuncio se permiten solicitudes publicitarias de Google durante la sesión y se carga y muestra el anuncio sin otra confirmación del juego. Un aviso visible en la tienda explica que Google carga el anuncio. UMP se consulta después de pulsar y puede mostrar el formulario de privacidad necesario de Google. Sin pulsar un botón publicitario, el juego no solicita anuncios. En Ajustes puedes detener nuevas solicitudes; esto no cancela una solicitud en curso, no detiene todo el tratamiento de un SDK ya inicializado ni elimina datos enviados a Google. El permiso no se conserva al reiniciar o recrear la Activity. Aceptar la política del juego por sí solo no permite solicitudes publicitarias. Los permisos del identificador publicitario y de Privacy Sandbox se excluyen del manifiesto; otros identificadores disponibles pueden tratarse. Ver anuncios es opcional. Una visualización con recompensa confirmada da al menos 5 000 restos, con un importe que crece según los planetas desbloqueados y los ingresos de la flota. Tres visualizaciones confirmadas dan una caja común. El contador para la caja y el identificador, tipo e importe mostrado de la recompensa pendiente se guardan localmente para evitar duplicados. Cerrar un anuncio sin ganar la recompensa no cuenta. Los bonos no son dinero. Las cajas se obtienen con restos del juego o anuncios con recompensa. No hay compras con dinero real.'
}
foreach ($dir in $sections.Keys) {
 $path=Join-Path $root "app/src/main/res/$dir/privacy.xml"
 $source=[IO.File]::ReadAllText($path)
 $heading=$sections[$dir].Split('\')[0]
 $pattern=[regex]::Escape($heading)+'\\n.*?(?=\\n\\n|</string>)'
 if (![regex]::IsMatch($source,$pattern)) { throw "Missing advertising section: $dir" }
 $replacement=$sections[$dir]
 $source=[regex]::Replace($source,$pattern,[Text.RegularExpressions.MatchEvaluator]{ param($match) $replacement })
 [IO.File]::WriteAllText($path,$source,$utf8)
}
& (Join-Path $PSScriptRoot 'Export-PrivacyPolicy.ps1')
